      const source = flag("source");
      const format = flag("format") || "summary";
      const out = flag("out");
      if (bool("auto")) {
        const src = tabId(m, source || listTabs(m).find((t) => t.id === target)?.derived_from);
        const found = autoMap(m, src, target);
        m.mappings = [...m.mappings || [], ...found];
        if (found.length) save(p, m);
        console.log(`Auto-mapped ${found.length} attribute(s) from ${tabLabel(m, src)} into ${tabLabel(m, target)}.`);
      }
      const cov = mappingCoverage(m, target);
      let text2;
      if (format === "csv") text2 = mappingsCsv(m, target);
      else if (format === "dbt") text2 = tabView(m, target).entities.map((e) => `-- models/${e.name}.sql
${mappingSql(m, target, e.name)}`).join("\n");
      else if (format === "md") text2 = tablesToMarkdown(tabView(m, target), buildDocTables(tabView(m, target), { sections: ["mappings"] }));
      else text2 = cov.byEntity.map((x) => `${x.entity.padEnd(32)} ${x.mapped}/${x.total}`).join("\n") + `

${cov.mapped} of ${cov.total} attributes mapped (${cov.pct}%).`;
      if (out) {
        writeFileSync3(out, text2);
        console.log(`Wrote ${out}`);
      } else process.stdout.write(text2.endsWith("\n") ? text2 : text2 + "\n");
