      if (!SQL_DIALECTS.some((d) => d.id === dialect)) fail3(`--dialect must be one of ${SQL_DIALECTS.map((d) => d.id).join(", ")}.`);
      const sql = migrationSql(m, a, b, dialect);
      const out = flag("out");
